//! Fixture-driven tests: every case in `fixtures/runs/` is checked against
//! (1) the hand-written exact expectations in `fixtures/expected/`,
//! (2) prefix verdict checks embedded in the fixture,
//! (3) the independent set-based oracle (open and closed).
//!
//! None of these answers are generated by the kernel under test.

mod common;

use common::*;

use btmon::lang::Verdict;
use btmon::monitor::{Limits, Monitor};
use serde_json::Value;

fn verdict_str(v: Verdict) -> &'static str {
    match v {
        Verdict::Sat => "sat",
        Verdict::Viol => "viol",
        Verdict::Wait => "wait",
    }
}

fn assert_expected(d: &mut Driven, expected: &Value) {
    // Open verdict and exact open-state obligations (kernel vs oracle).
    let open_oracle = oracle_open(d);
    assert_kernel_matches_oracle(&d.monitor, &open_oracle);
    assert_eq!(
        verdict_str(d.monitor.global_verdict()),
        expected["open_verdict"].as_str().unwrap(),
        "{}: open verdict mismatch",
        d.run_id
    );

    let closed = d.monitor.end().expect("close");
    let closed_oracle = oracle_closed(d);
    assert_kernel_matches_oracle(&d.monitor, &closed_oracle);
    assert_eq!(
        verdict_str(closed.verdict),
        expected["closed_verdict"].as_str().unwrap(),
        "{}: closed verdict mismatch",
        d.run_id
    );

    let expected_instances = expected["instances"].as_array().unwrap();
    assert_eq!(
        d.monitor.obligations.len(),
        expected_instances.len(),
        "{}: instance count",
        d.run_id
    );
    for exp in expected_instances {
        let id = exp["id"].as_str().unwrap();
        let o = d
            .monitor
            .obligations
            .iter()
            .find(|o| o.id == id)
            .unwrap_or_else(|| panic!("{}: missing obligation {id}", d.run_id));
        assert_eq!(
            serde_json::to_value(o.status).unwrap().as_str().unwrap(),
            exp["status"].as_str().unwrap(),
            "{id}: status"
        );
        assert_eq!(
            serde_json::to_value(o.reason).unwrap().as_str().unwrap(),
            exp["reason"].as_str().unwrap(),
            "{id}: reason"
        );
        assert_eq!(
            o.window_start,
            exp["window"][0].as_i64().unwrap(),
            "{id}: window_start"
        );
        assert_eq!(
            o.window_end,
            exp["window"][1].as_i64().unwrap(),
            "{id}: window_end"
        );
        assert_eq!(
            o.satisfied_at,
            exp["satisfied_at"].as_i64(),
            "{id}: satisfied_at"
        );
        assert_eq!(o.failed_at, exp["failed_at"].as_i64(), "{id}: failed_at");
    }
    log_run(file!(), d);
    log_line(
        file!(),
        &d.run_id,
        "closed",
        serde_json::to_value(d.monitor.status()).unwrap(),
    );
}

