#[test]
fn case_09_rotation_seals_epochs() {
    let f = load_run("09-rotation");
    let mut d = drive(&f);
    assert_expected(&mut d, &load_expected("09-rotation"));
    // Extra version-isolation assertions.
    assert_eq!(d.monitor.active_epoch, 1);
    assert_eq!(d.monitor.rulesets.len(), 2);
    let epoch0: Vec<_> = d
        .monitor
        .obligations
        .iter()
        .filter(|o| o.epoch == 0)
        .collect();
    let epoch1: Vec<_> = d
        .monitor
        .obligations
        .iter()
        .filter(|o| o.epoch == 1)
        .collect();
    assert_eq!(epoch0.len(), 1);
    assert_eq!(epoch1.len(), 2);
    assert!(epoch0
        .iter()
        .all(|o| o.status != btmon::lang::ObligationStatus::Pending));
}

