// ----------------------------------------------------------- prefix checks
/// Re-drive each fixture and assert its embedded `open_checks` prefix
/// verdicts. Critically: an open trace with pending obligations must yield
/// `wait`, never `sat`.
#[test]
fn prefix_verdicts_are_three_valued() {
    let cases = [
        "03-missing-early",
        "04-lenient",
        "05-sustain-fail",
        "06-sustain-incomplete",
        "10-mixed",
    ];
    for name in cases {
        let f = load_run(name);
        assert!(!f.open_checks.is_empty(), "{name} should embed open_checks");
        // Drive incrementally so we can inspect prefixes.
        let mut monitor = Monitor::new(
            "prefix".into(),
            f.run_id.clone(),
            f.segments[0].ruleset.clone(),
            Limits::replay(),
        )
        .unwrap();
        for (idx, seg) in f.segments.iter().enumerate() {
            if idx > 0 {
                monitor.rotate(seg.ruleset.clone()).unwrap();
            }
            for v in &seg.events {
                let ev = match v.get("event") {
                    Some(inner) => serde_json::from_value(inner.clone()).unwrap(),
                    None => serde_json::from_value(v.clone()).unwrap(),
                };
                monitor.append(&ev, None).unwrap();
                let fed = monitor.next_step as usize;
                for check in &f.open_checks {
                    if check.after_events == fed {
                        assert_eq!(
                            verdict_str(monitor.global_verdict()),
                            check.global_verdict,
                            "{name} prefix after {fed} events"
                        );
                        log_line(
                            file!(),
                            &f.run_id,
                            "prefix_check",
                            serde_json::json!({
                                "after_events": check.after_events,
                                "verdict": verdict_str(monitor.global_verdict()),
                                "pending": monitor.pending_count(),
                            }),
                        );
                    }
                }
            }
        }
    }
}

/// A wait on an open trace must never collapse to sat after merely adding
/// more irrelevant events without closing.
#[test]
fn wait_is_not_pass_while_open() {
    let f = load_run("03-missing-early");
    let mut d = drive(&f);
    assert_eq!(d.monitor.global_verdict(), Verdict::Wait);
    use btmon::lang::Event;
    d.monitor.append(&Event::new("noise"), None).unwrap(); // t3: window [1,3] ends here -> actually becomes violated
    assert_eq!(d.monitor.global_verdict(), Verdict::Viol);

    // Fresh run where the deadline remains open and keep feeding noise:
    // verdict must stay wait, never sat.
    let f2 = load_run("04-lenient"); // window [1,3], ends at t2
    let d2 = drive(&f2);
    assert_eq!(d2.monitor.global_verdict(), Verdict::Wait);
}
